def pancake_sort(nums):
    """Write a function to sort a list of elements using pancake sort.

    Repeatedly bring the largest unsorted element to the front by
    reversing a prefix, then reverse the whole unsorted prefix to move
    it to its final position. Returns a new sorted list and does not
    mutate the input.
    """
    result = list(nums)

    def flip(end):
        """Reverse the prefix result[:end + 1] in place."""
        left, right = 0, end
        while left < right:
            result[left], result[right] = result[right], result[left]
            left += 1
            right -= 1

    for curr_size in range(len(result), 1, -1):
        max_idx = 0
        for i in range(1, curr_size):
            if result[i] > result[max_idx]:
                max_idx = i
        if max_idx == curr_size - 1:
            continue
        if max_idx != 0:
            flip(max_idx)
        flip(curr_size - 1)
    return result
